<?php require_once 'auth.php';require_admin();require_once 'material-utils.php';$pdo=db();$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$code=trim($_POST['code']??'');$notes=trim($_POST['notes']??'');$coef=(float)($_POST['coefficient']??0);if(!$pdo||$name===''||!preg_match('/^[a-z0-9-]+$/',$code)||$coef<0){header('Location: material-form.php?error=Vui lòng kiểm tra lại thông tin'.($id?'&id='.$id:''));exit;}$image=isset($_FILES['image'])?material_upload($_FILES['image']):null;try{if($id){$sql='UPDATE materials SET name=?,code=?,coefficient=?,notes=?'.($image?',image=?':'').' WHERE id=?';$values=[$name,$code,$coef,$notes?:null];if($image)$values[]=$image;$values[]=$id;$pdo->prepare($sql)->execute($values);$msg='Đã lưu chất liệu';}else{$pdo->prepare('INSERT INTO materials(name,code,coefficient,notes,image) VALUES(?,?,?,?,?)')->execute([$name,$code,$coef,$notes?:null,$image]);$msg='Đã tạo chất liệu';}header('Location: materials.php?ok='.urlencode($msg));}catch(Throwable $e){header('Location: material-form.php?error='.urlencode('Không thể lưu, mã có thể đã tồn tại').($id?'&id='.$id:''));}
